package com.aaliyun.leadnews.behavior.config;
import java.time.Duration;
import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties("leadnews.behavior") public class BehaviorProperties {private String topic="leadnews.behavior.events";private String dltTopic="leadnews.behavior.events.DLT";private long sendTimeoutMillis=5000;private long pendingRetryMillis=5000;private int consumedEventRetentionDays=30;private Duration likeCooldown=Duration.ofHours(1);private Duration collectCooldown=Duration.ofHours(1);private int likeFirstHeat=2,likeRepeatHeat=1,likeCancelHeat=1,collectFirstHeat=5,collectRepeatHeat=2,collectCancelHeat=2;public String getTopic(){return topic;}public void setTopic(String v){topic=v;}public String getDltTopic(){return dltTopic;}public void setDltTopic(String v){dltTopic=v;}public long getSendTimeoutMillis(){return sendTimeoutMillis;}public void setSendTimeoutMillis(long v){sendTimeoutMillis=v;}public long getPendingRetryMillis(){return pendingRetryMillis;}public void setPendingRetryMillis(long v){pendingRetryMillis=v;}public int getConsumedEventRetentionDays(){return consumedEventRetentionDays;}public void setConsumedEventRetentionDays(int v){if(v<7)throw new IllegalArgumentException("consumedEventRetentionDays must be >= 7");consumedEventRetentionDays=v;}public Duration getLikeCooldown(){return likeCooldown;}public void setLikeCooldown(Duration v){likeCooldown=v;}public Duration getCollectCooldown(){return collectCooldown;}public void setCollectCooldown(Duration v){collectCooldown=v;}public int getLikeFirstHeat(){return likeFirstHeat;}public void setLikeFirstHeat(int v){likeFirstHeat=v;}public int getLikeRepeatHeat(){return likeRepeatHeat;}public void setLikeRepeatHeat(int v){likeRepeatHeat=v;}public int getLikeCancelHeat(){return likeCancelHeat;}public void setLikeCancelHeat(int v){likeCancelHeat=v;}public int getCollectFirstHeat(){return collectFirstHeat;}public void setCollectFirstHeat(int v){collectFirstHeat=v;}public int getCollectRepeatHeat(){return collectRepeatHeat;}public void setCollectRepeatHeat(int v){collectRepeatHeat=v;}public int getCollectCancelHeat(){return collectCancelHeat;}public void setCollectCancelHeat(int v){collectCancelHeat=v;}}
